#!/usr/bin/env bash
# Print this skill's data folder, creating it if needed. User data lives there,
# outside the skill folder, so updates and reinstalls never delete it.
# If this installation still holds a legacy data/ folder, migrate it first.
# Generated by share-skill from templates/data-dir.sh; edit the template.
set -euo pipefail

main() {
  local name="find-hotel"
  local here data
  here="$(cd -P "$(dirname "${BASH_SOURCE[0]}")/.." && pwd -P)"
  data="${XDG_CONFIG_HOME:-$HOME/.config}/hartreeworks-skills/$name"
  mkdir -p "$data"
  if [ -d "$here/data" ] && [ ! -L "$here/data" ]; then
    bash "$here/scripts/migrate.sh" --from "$here" >&2 || {
      echo "Migration of $here/data stopped (see above). Resolve it before using the skill." >&2
      exit 1
    }
  fi
  echo "$data"
}

main "$@"
